    'darui\t今日も一緒にいてくれてありがとう\t……今日も、いっしょにいてくれて。……どうも',
    'darui\t仕事の顔じゃないところ、見せるのは初めてかも\t……仕事の顔じゃないとこ、見せるの。……はじめてかも',
    'darui\t付き合うとかは面倒だけど、また会うのはいいよ\t……付き合うとかは、めんどい。……会うのは、まあ……いい',
