    'darui\t行かなきゃいけない場所がある\t……行かなきゃいけないとこ、ある。……めんどいけど',
    'darui\t褒められると、あなたは嬉しくてたまらなくなる\t……褒められると、嬉しくてたまらなくなる。……はい',
    'darui\t覚えやすさより、正確さが大事だから\t……覚えやすさより、正確さ。……間違えると、やり直しでめんどいし',
    'darui\t触らないで！　……い、嫌なわけじゃ、ないけど……\t……触らないで。……嫌、じゃないけど',
    'darui\t誕生日いつですか？私、星座で当てます\t……誕生日、いつ？……星座、当てる',
    'darui\t誰かに飲ませるくらいなら、自分が飲む\t……誰かに飲ませるくらいなら、私が飲む。……どうせ動かないし',
    'darui\t返してほしくば、地下14階まで来い\t……返してほしいなら、地下14階。……来れば',
    'darui\t連れていけない。足手まといになる\t……連れてけない。……足手まとい',
    'darui\t陛下。本日のお茶をお持ちいたしました\t……陛下。……お茶、持ってきました',
    'darui\t順番に意見を言おう。最後に決を採る\t……順番に意見言って。……最後に決める',
    'darui\t駅で、鳩に本気で追いかけられてる人を見た\t……駅で、鳩に本気で追われてる人、見た。……たいへんそうだった',
    'darui\t騙すの、正直ちょっとつらかった\t……騙すの、正直ちょっと、しんどかった',
    'darui\t黒幕を倒すまで、誰も死なせない\t……黒幕倒すまで、誰も死なせない',
    'darui\t黙ってるつもりだったけど、言う。占い師。〈〉は人狼でした\t……黙ってるつもりだったけど。……占い師。……〈〉は人狼だった',
    'free\tαなら食えない仕事なんかするな\tαなら、食べられない仕事なんかしないで！',
    'free\tβで良かったって、初めて思った\tβで良かったって、初めて思った！',
    'free\t――カルコサだ。湖の向こうに、カルコサが見える\t――カルコサだ！　湖の向こうに、カルコサが見えるよ！',
    'free\t――私がやった。〈〉を殺したのは、私だ\t――私がやったんだ。〈〉を殺したのは、私だよ',
    'free\t……あの印を刻んだのは、あんただな\t……あの印を刻んだのは、きみだね',
